export const portfolios={sp:{name:'S&P 500 · VOO / SPY',mu:.07,sigma:.18,yield:.016,hist:1},us:{name:'Total US market · VTI',mu:.07,sigma:.19,yield:.016,hist:1,proxy:true},global:{name:'Global equities · VT',mu:.065,sigma:.18,yield:.025},intl:{name:'International equities · VXUS',mu:.065,sigma:.20,yield:.03},balanced:{name:'60% stocks / 40% Treasuries',mu:.055,sigma:.115,yield:.025,hist:1},treasury:{name:'10-year Treasury portfolio',mu:.04,sigma:.075,yield:.04,hist:1},cash:{name:'Cash / money market',mu:.03,sigma:.008,yield:.03,hist:1},custom:{name:'Custom diversified portfolio',mu:.06,sigma:.20,yield:.02},stock:{name:'Concentrated / individual stock',mu:.06,sigma:.40,yield:0}};
export const allocations=[{name:'Mortgage',mort:1,invest:0,cash:0},{name:'75% mortgage',mort:.75,invest:.25,cash:0},{name:'50 / 50',mort:.5,invest:.5,cash:0},{name:'25% mortgage',mort:.25,invest:.75,cash:0},{name:'Invest',mort:0,invest:1,cash:0},{name:'Keep liquid',mort:0,invest:0,cash:1},{name:'Thirds',mort:1/3,invest:1/3,cash:1/3}];
export function payment(b,r,n){const i=r/12;return i===0?b/n:b*i/(-Math.expm1(-n*Math.log1p(i)));}
export function deduction(interest,c){if(!c.taxOn)return 0;const eligible=interest*c.eligible;return (Math.max(0,c.otherDed+eligible-c.standard)-Math.max(0,c.otherDed-c.standard))*c.incomeTax;}
function makeSchedule(c,a){let b=c.balance,paid=0,int=0,annual=0;const p=payment(b,c.rate,c.term*12),n=c.horizon*12;let reserve=c.cash;const protectedLump=Math.min(c.lump,Math.max(0,c.reserve-reserve));reserve+=protectedLump;let lump=c.lump-protectedLump;const initialMort=Math.min(b,lump*a.mort);b-=initialMort;const initialInvest=lump*a.invest+Math.max(0,lump*a.mort-initialMort)*(a.cash===1?0:1);const initialCash=lump*a.cash;let payoff=b<.005?0:null;let flows=[];
for(let m=0;m<n;m++){let extra=c.extra,topup=Math.min(extra,Math.max(0,c.reserve-reserve));reserve+=topup;extra-=topup;const interest=b*c.rate/12;int+=interest;annual+=interest;const due=b+interest,normal=Math.min(p,due),pre=Math.min(extra*a.mort,Math.max(0,due-normal));b=Math.max(0,due-normal-pre);paid+=normal+pre;const free=p-normal+extra*a.mort-pre;let invest=extra*a.invest+(a.cash===1?0:free),cash=topup+extra*a.cash+(a.cash===1?free:0);let refund=0;if((m+1)%12===0){refund=deduction(annual,c);annual=0;}flows.push({invest,cash,refund,balance:b,interest,spent:normal+pre});if(b<.005&&payoff===null)payoff=m+1;}
return {p,initialMort,initialInvest,initialCash,protectedLump,flows,balance:b,interest:int,payoff,initialReserve:c.cash+protectedLump};}
const scheduleCache=new WeakMap();
export function schedule(c,a){if(!scheduleCache.has(c))scheduleCache.set(c,new Map());const cache=scheduleCache.get(c);if(!cache.has(a))cache.set(a,makeSchedule(c,a));return cache.get(a);}
export function simulate(c,a,returns,trace=false){const s=schedule(c,a);let taxable=0,basis=0,retirement=0,cash=s.initialReserve+s.initialCash,used=0;const tax=c.taxOn?c: {...c,incomeTax:0,gainsTax:0,divTax:0,withdrawTax:0};
function contribute(dollars){if(c.account==='taxable'){taxable+=dollars;basis+=dollars;return;}const gross=c.account==='traditional'||c.account==='hsa'?dollars/(1-tax.incomeTax):dollars;const take=Math.min(gross,Math.max(0,c.room-used));used+=take;retirement+=take;const spent=take*(c.account==='traditional'||c.account==='hsa'?1-tax.incomeTax:1);taxable+=Math.max(0,dollars-spent);basis+=Math.max(0,dollars-spent);}
contribute(s.initialInvest);let series=[];const afterTax=()=>taxable-Math.max(0,taxable-basis)*tax.gainsTax;const retireNet=()=>retirement*(c.account==='traditional'?1-tax.withdrawTax:1);const liquid=()=>cash+afterTax()+(c.account!=='taxable'&&c.access?retireNet():0);
const point=(m,b)=>({year:m/12,wealth:cash+afterTax()+retireNet()+c.balance-b,liquid:liquid(),cash,balance:b,assets:cash+afterTax()+retireNet()});if(trace)series.push(point(0,c.balance-s.initialMort));
for(let m=0;m<s.flows.length;m++){if(m>0&&m%12===0)used=0;const y=Math.floor(m/12),r=returns[y],monthly=Math.pow(1+r,1/12)-1,fee=Math.pow(1-c.fee,1/12);const yieldRate=(c.dividendYield??portfolios[c.portfolio]?.yield??.02)/12;const incomeRate=(c.portfolio==='treasury'||c.portfolio==='cash')?tax.incomeTax:tax.divTax;const dividend=taxable*yieldRate;taxable=taxable*(1+monthly)*fee-dividend*incomeRate;taxable=Math.max(0,taxable);basis+=dividend*(1-incomeRate);retirement=Math.max(0,retirement*(1+monthly)*fee);if(cash>0)cash*=Math.pow(1+c.cashReturn*(1-tax.incomeTax),1/12);const f=s.flows[m];contribute(f.invest);cash+=f.cash;taxable+=f.refund;basis+=f.refund;if(c.expense&&m===35){cash-=c.expense;if(cash<0&&taxable>0){const t=tax.gainsTax*Math.max(0,taxable-basis)/taxable;const sell=Math.min(taxable,-cash/(1-t));basis*=1-sell/taxable;taxable-=sell;cash+=sell*(1-t);}if(cash<0&&c.access&&retirement>0){const t=c.account==='traditional'?tax.withdrawTax:0;const take=Math.min(retirement,-cash/(1-t));retirement-=take;cash+=take*(1-t);}}if(trace&&(m+1)%12===0)series.push(point(m+1,f.balance));}
const end=point(s.flows.length,s.balance);return {...end,series,payoff:s.payoff,interest:s.interest,payment:s.p,protectedLump:s.protectedLump,retirement:retireNet(),taxable:afterTax()};}
export const quantile=(values,q)=>{const s=[...values].sort((a,b)=>a-b),p=(s.length-1)*q,i=Math.floor(p);return s[i]+(s[Math.min(i+1,s.length-1)]-s[i])*(p-i);};
const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
function rng(seed=20261003){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
export function paths(c,history){const random=rng(),z=()=>Math.sqrt(-2*Math.log(Math.max(1e-9,random())))*Math.cos(2*Math.PI*random());const n=c.horizon,p=portfolios[c.portfolio],mu=c.mu,sig=c.sigma;const historic=history.map(r=>c.portfolio==='balanced'?.6*r[1]+.4*r[3]:c.portfolio==='treasury'?r[3]:c.portfolio==='cash'?r[2]:r[1]);let views=[];
if(p.hist){let rolling=[];for(let i=0;i<=historic.length-n;i++)rolling.push(historic.slice(i,i+n));views.push({name:'Historical rolling periods',type:'Historical evidence',paths:rolling,description:`${history[0][0]}–${history.at(-1)[0]}; overlapping calendar-year windows. ${p.proxy?'S&P 500 proxy for total US stocks. ':''}Annual returns smoothed within each year; not actual monthly experience.`});let boot=[];for(let k=0;k<250;k++){let row=[];while(row.length<n){const start=Math.floor(random()*(historic.length-2));row.push(...historic.slice(start,start+3));}boot.push(row.slice(0,n));}views.push({name:'Historical block resampling',type:'Model estimate',paths:boot,description:'250 paths using contiguous 3-year blocks of observed returns; synthetic sequences, not historical frequencies.'});}
let conventional=[],forward=[],regime=[];for(let k=0;k<350;k++){let base=[],fwd=[],reg=[],state=2;for(let y=0;y<n;y++){const noise=z();base.push(Math.expm1(Math.log1p(mu)-sig*sig/2+sig*noise));const adj=y<10?(c.valuation==='high'?-.02:c.valuation==='low'?.02:-.01):0;fwd.push(Math.expm1(Math.log1p(mu+adj)-sig*sig/2+sig*noise));if(random()>.7)state=Math.floor(random()*4);const shift=[-.12,.02,.05,-.035][state];reg.push(Math.expm1(Math.log1p(Math.max(-.8,mu+shift))-sig*sig/2+sig*z()));}conventional.push(base);forward.push(fwd);regime.push(reg);}
views.push({name:'Conventional probability model',type:'Model estimate',paths:conventional,description:'350 independent annual lognormal paths. Expected arithmetic return and log-return volatility are editable assumptions.'},{name:'Starting-condition stress model',type:'Illustrative assumption',paths:forward,description:'350 paths; first 10 years shift expected returns −1 point (neutral), −2 (high valuation), or +2 (low). No live valuation data or calibrated forecast.'},{name:'Persistent market environments',type:'Illustrative assumption',paths:regime,description:'350 paths; recession, inflation, growth and weak-return states. 70% annual state persistence; heuristic shifts, not calibrated probabilities.'});
for(const v of views)v.paths=v.paths.map(row=>scenario(row,c.scenario,mu,c.portfolio,c.cashReturn));if(c.portfolio==='cash')for(const v of views)v.paths=v.paths.map(row=>row.map(r=>Math.max(0,r)));return views;}
export function scenario(row,name,mu,portfolio='sp',cashReturn=.03){const crash=portfolio==='balanced'?-.186:portfolio==='treasury'?.06:portfolio==='cash'?cashReturn:-.35;return row.map((r,y)=>name==='crash'&&y===0?crash:name==='lost'&&y<10?Math.expm1(Math.log1p(r)-Math.log1p(mu)):name==='bull'&&y<5?Math.min(1,r+.08):name==='low'?Math.max(-.9,r-.03):r);}
export function analyze(c,history){const views=paths(c,history);let results=views.map(v=>{const outcomes=allocations.map(a=>v.paths.map(row=>simulate(c,a,row)));const diffs=outcomes[4].map((r,i)=>r.wealth-outcomes[0][i].wealth);const summaries=outcomes.map((r,i)=>({name:allocations[i].name,mean:mean(r.map(x=>x.wealth)),median:quantile(r.map(x=>x.wealth),.5),p10:quantile(r.map(x=>x.wealth),.1),p90:quantile(r.map(x=>x.wealth),.9),liquid:quantile(r.map(x=>x.liquid),.5),payoff:r[0].payoff}));let regrets=allocations.map((a,i)=>quantile(outcomes[i].map((r,k)=>Math.max(...outcomes.map(o=>o[k].wealth))-r.wealth),.9));return {...v,outcomes,summaries,diffs,win:diffs.filter(x=>x>1).length/diffs.length,median:quantile(diffs,.5),down:quantile(diffs,.1),up:quantile(diffs,.9),best:summaries.reduce((best,s,i)=>s.mean>summaries[best].mean?i:best,0),robust:regrets.indexOf(Math.min(...regrets)),regrets};});
const focus=results.find(v=>v.name==='Conventional probability model');const agree=results.filter(v=>(v.median>=0)===(focus.median>=0)).length;const rank=focus.summaries.map((s,i)=>({...s,index:i})).sort((a,b)=>b.mean-a.mean);const breaks=breakEven(c);return {views:results,focus,agree,rank,breakEven:breaks,robust:agree===results.length&&results.every(v=>focus.median>=0?v.win>=.65:v.win<=.35)&&Math.abs(c.mu-breaks)>.02&&c.portfolio!=='stock'&&c.portfolio!=='custom'&&c.portfolio!=='global'&&c.portfolio!=='intl'?'Strong within these models':agree===results.length?'Moderate':'Sensitive · models disagree'};}
export function breakEven(c){const diff=r=>{let row=Array(c.horizon).fill(r);return simulate(c,allocations[4],row).wealth-simulate(c,allocations[0],row).wealth;};if(c.extra===0&&c.lump===0)return NaN;let lo=-.5,hi=.5;if(Math.abs(diff(0))<.01&&Math.abs(diff(.1))<.01)return NaN;if(diff(lo)*diff(hi)>0)return NaN;for(let i=0;i<40;i++){const mid=(lo+hi)/2;if(diff(mid)>0)hi=mid;else lo=mid;}return (lo+hi)/2;}
export function mortgageYield(c){const amount=Math.min(1000,c.balance),cfg={...c,cash:0,reserve:0,extra:0,lump:0},base=schedule(cfg,allocations[0]),pre=schedule({...cfg,lump:amount},allocations[0]);const flows=base.flows.map((f,i)=>f.spent-pre.flows[i].spent+pre.flows[i].refund-f.refund);flows[flows.length-1]+=base.balance-pre.balance;const npv=annual=>-amount+flows.reduce((sum,f,i)=>sum+f/Math.pow(1+annual,(i+1)/12),0);let lo=-.5,hi=.5;for(let k=0;k<50;k++){const mid=(lo+hi)/2;if(npv(mid)>0)lo=mid;else hi=mid;}return (lo+hi)/2;}
